 a=read(PUBLIC/'decision_exports.json');v=read(PUBLIC/'verification.json');q=read(PUBLIC/'qualification_summary.json');attempt=read(PUBLIC/'attempt.json');assert v['passed'];verdict=grade(a['runs'],a['mirror_checks'],a['level_flags']);assert verdict==a['verdict'];rows=a['runs'];floor=np.array([r['floor'] for r in a['coarse_null_floors']]);maximum_mirror=max(r['max_velocity_sum'] for r in a['mirror_checks']);levelmedian=sum(r['median_above_floor'] for r in a['level_flags']);levelmax=sum(r['maximum_block_above_floor'] for r in a['level_flags']);ratios=[]
