 axes[2].axhline(.6,color='black',ls='--',lw=1);axes[2].axvspan(100,400,color='gray',alpha=.08);axes[2].set(xlabel='Model time',ylabel='Core depth / cached reference depth',title='Fine-grid upper-level viability fails');axes[2].legend(fontsize=8);axes[2].text(.04,.10,'Missing core measurements are not filled.\nShading: qualification window.',transform=axes[2].transAxes,fontsize=8);fig.savefig(PUBLIC/'MG191_summary.png',dpi=160);plt.close(fig)
